GfxTextureHandle Hardware::CreateTexture()
{
    std::unique_ptr<GPUTexture> texture = std::unique_ptr<GPUTexture>(new GPUTexture());

    u32 id;
    if (!freeTextures.empty())
    {
        id = freeTextures.back();
        freeTextures.pop_back();
        textures[id] = std::move(texture);
    }
    else
    {
        id = textures.size();
        textures.push_back(std::move(texture));
    }

    return {id};
}

void Hardware::BindTexture(GfxTextureHandle handle)
{
    if (handle >= textures.size())
        return;
    if (!textures[handle.id])
        return;
    boundTexture = textures[handle.id].get();
}

void Hardware::DeleteTexture(GfxTextureHandle handle)
{
    if (handle.id >= textures.size())
        return;
    if (!textures[handle.id])
        return;
    textures[handle.id].reset();
    freeTextures.push_back(handle.id);
}

inline SDL_PIXEL_FORMAT_COMPAT GetSDLPixelFormat(PixelFormat fmt, PixelDataType type) {
    switch(type) {
        case PIXEL_UNSIGNED_BYTE:
            if(fmt == PIXEL_RGB) return SDL_PIXELFORMAT_RGB24;
            else return SDL_PIXELFORMAT_RGBA32;
        case PIXEL_UNSIGNED_SHORT_4_4_4_4:
            return SDL_PIXELFORMAT_RGBA4444;
        case PIXEL_UNSIGNED_SHORT_5_5_5_1:
            return SDL_PIXELFORMAT_RGBA5551;
        case PIXEL_UNSIGNED_SHORT_5_6_5:
            return SDL_PIXELFORMAT_RGB565;
    }
}

void Hardware::SetTextureImage(u32 width, u32 height, PixelFormat fmt, PixelDataType type, const void* data) {
    if (boundTexture) {
        SDL_GPUTextureCreateInfo texInfo = {};
        texInfo.type = SDL_GPU_TEXTURETYPE_2D;
        texInfo.format = SDL_GPU_TEXTUREFORMAT_R8G8B8A8_UNORM;
        texInfo.width = width;
        texInfo.height = height;
        texInfo.layer_count_or_depth = 1;
        texInfo.num_levels = 1;
        texInfo.usage = SDL_GPU_TEXTUREUSAGE_SAMPLER;

        boundTexture->gpuTexture =
            SDL_CreateGPUTexture(device, &texInfo);
    }
}

