void Hardware::ReadPixels(i32 x, i32 y, i32 width, i32 height, const void* pixels) {
    u8* dst = (u8*)pixels;
    i32 pitch = width * 4;
    for (i32 row = 0; row < height; row++) {
        const u8* src = (u8*)framebuffer + ((g_GameWindow.GAME_WINDOW_HEIGHT_REAL - 1 - (y + row)) * g_GameWindow.GAME_WINDOW_WIDTH_REAL + x) * 4;
        memcpy(dst + row * pitch, src, pitch);
    }
}

void Hardware::Draw(
    PrimitiveType type,
    int start,
    int count)
{
    SDL_GPUBufferCreateInfo bufferInfo = {};
    bufferInfo.usage = SDL_GPU_BUFFERUSAGE_VERTEX;
    bufferInfo.size = count;

    vertexBuffer = SDL_CreateGPUBuffer(
        device,
        &bufferInfo);

    vertexBinding.buffer = vertexBuffer;
    
    SDL_BindGPUGraphicsPipeline(
        renderPass,
        pipeline);

    SDL_BindGPUVertexBuffers(
        renderPass,
        0,
        &vertexBinding,
        1);

    SDL_GPUTextureSamplerBinding samplerBinding = {};

    samplerBinding.texture = boundTexture->gpuTexture;

    samplerBinding.sampler =
        gpuSampler;

    SDL_BindGPUFragmentSamplers(
        renderPass,
        0,
        &samplerBinding,
        1);

    SDL_DrawGPUPrimitives(
        renderPass,
        count,
        1,
        start,
        0);
}

void Hardware::SwapBuffers()
{
    SDL_UpdateTexture(framebufferTexture, NULL, framebuffer, g_GameWindow.GAME_WINDOW_WIDTH_REAL * sizeof(u32));
    SDL_RenderCopy(renderer, framebufferTexture, NULL, NULL);
    SDL_RenderPresent(renderer);
}